	case(state)
		LOAD :cycles	=  'd384   ;
		YVER :cycles    =  'd132   ;
        YHOR :cycles    =  'd140   ;
		CVER :cycles    =  'd68    ;
        CHOR :cycles    =  'd76    ;
       OUTLT :cycles	=  'd67    ;
	   OUT   :cycles	=  'd384   ;
     default :cycles	=  'd0	   ;
	endcase
