		cnt_r	<=	8'd0;
	else if(!state)
		cnt_r	<=	8'd0;	
	else if(cnt_r	==	cycles)
		cnt_r	<=	8'd0;
	else 
        cnt_r	<=	cnt_r	+	1'b1;
