      S1: begin
        if (data[2:0] == 3'b010) next_state = S2;
        else next_state = S0;
      end
      S2: begin
        if (data[2:0] == 3'b100) next_state = S3;
        else next_state = S0;
      end
      S3: begin
        next_state = S0;
      end
    endcase
  end

endmodule

